// Build a no-user-media RELAY-001-compatible fixture from real native CI receipts.
// A synthetic MP3 is generated by ffmpeg in the workflow. Never ship as real song.
import {readFile,writeFile,mkdir,copyFile} from 'node:fs/promises';
import {join,resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
const [packetRoot,donorDir,thirdPublic,webzProof]=process.argv.slice(2);
if(!packetRoot||!donorDir||!thirdPublic||!webzProof)throw Error('fixture args: ROOT DONOR_DIR THIRD_PUBLIC WEBZ_MODULE');
const root=resolve(packetRoot),donor=resolve(donorDir),third=resolve(thirdPublic);
const sha=b=>createHash('sha256').update(b).digest('hex');
const readJSON=async p=>JSON.parse(await readFile(p,'utf8'));
async function save(p,x){const dest=join(root,p);await mkdir(join(dest,'..'),{recursive:true});await writeFile(dest,JSON.stringify(x,null,2)+'\n')}
async function copy(p,src){const dest=join(root,p);await mkdir(join(dest,'..'),{recursive:true});await copyFile(src,dest)}
for(const name of ['loadout-binding.json','loadout-parameters.json','ghot-task.json','ghot-receipt.json','relay-crossing.json'])
 await copy('crossing/native-song-evidence/'+name,join(donor,name));
for(const name of ['roundtrip-result.json','transport-bundle.json','verification.json'])
 await copy('third-organ/public/'+name,join(third,name));
const native=await readJSON(join(donor,'relay-crossing.json'));
const ghot=await readJSON(join(donor,'ghot-receipt.json'));
const signed=await readJSON(join(third,'roundtrip-result.json'));
const audio=await readFile(join(root,'source/song.mp3'));
if(native.source_sha256!==sha(audio))throw Error('Fixture did not match native source SHA');
const art=Buffer.from('SYNTHETIC IMAGE PLACEHOLDER, NOT REAL COVER');
const lyric=Buffer.from('Synthetic test tone, no song lyrics.');
await writeFile(join(root,'source/embedded-cover.jpg'),art);
await writeFile(join(root,'source/lyrics-embedded.txt'),lyric);
const hash=sha(audio);
await save('seed.json',{schema:'static-relay/seed-v0',title:'Synthetic Relay Audio',
 artist:'test-only',suno_id_embedded:'synthetic-test-only',
 link_supplied_by_user:'https://suno.com/s/isV6mAiuOJSv8r38',
 audio_file:{path:'source/song.mp3',sha256:hash,size_bytes:audio.length,
  duration_seconds_ffprobe:Number(ghot.output.probe.format.duration)},
 embedded_artwork:{path:'source/embedded-cover.jpg',sha256:sha(art),derivation:'synthetic'},
 embedded_lyrics:{path:'source/lyrics-embedded.txt',sha256:sha(lyric),derivation:'synthetic'},
 rights:'fixture-only'});
const candidateNames=['LOADOUT','GHoT','reLATTE','webZ','SIA',...Array.from({length:34},(_,i)=>'synthetic-candidate-'+String(i+1))];
await save('mission.json',{schema:'static-relay/mission-v0',
 mission_id:'relay-001-blue-night-morning-bloom',candidate_organs:candidateNames.map(n=>({
 project:n,lane:'synthetic-ci',status:n==='SIA'?'PROPOSED_NOT_INVOKED':'PROPOSED_NOT_INVOKED'
 }))});
await save('fourth-organ/mission-fourth.json',{schema:'static-relay/mission-fourth-organ/v0',source_sha256:'sha256:'+hash});
const nativeProof=await import(pathToFileURL(resolve(webzProof)).href);
const observation=await nativeProof.inspectRelay(signed);
await save('fourth-organ/observation.json',observation);
console.log('PASS: built synthetic four-organ fixture, no user song included');
